class _PigeonCodec extends StandardMessageCodec {
  const _PigeonCodec();
  @override
  void writeValue(WriteBuffer buffer, Object? value) {
    if (value is int) {
      buffer.putUint8(4);
      buffer.putInt64(value);
    }    else if (value is IceServerMessage) {
      buffer.putUint8(129);
      writeValue(buffer, value.encode());
    }    else if (value is ConfigMessage) {
      buffer.putUint8(130);
      writeValue(buffer, value.encode());
    }    else if (value is StartOptionsMessage) {
      buffer.putUint8(131);
      writeValue(buffer, value.encode());
    }    else if (value is AccountConfigMessage) {
      buffer.putUint8(132);
      writeValue(buffer, value.encode());
    }    else if (value is AccountMessage) {
      buffer.putUint8(133);
      writeValue(buffer, value.encode());
    }    else if (value is CallMessage) {
      buffer.putUint8(134);
      writeValue(buffer, value.encode());
    }    else if (value is StartResultMessage) {
      buffer.putUint8(135);
      writeValue(buffer, value.encode());
    }    else if (value is CallInfoMessage) {
      buffer.putUint8(136);
      writeValue(buffer, value.encode());
    }    else if (value is MediaStatsMessage) {
      buffer.putUint8(137);
      writeValue(buffer, value.encode());
    }    else if (value is AudioDeviceMessage) {
      buffer.putUint8(138);
      writeValue(buffer, value.encode());
    }    else if (value is ExternalAudioFormatMessage) {
      buffer.putUint8(139);
      writeValue(buffer, value.encode());
    }    else if (value is AudioRouteMessage) {
      buffer.putUint8(140);
      writeValue(buffer, value.encode());
    }    else if (value is EventMessage) {
      buffer.putUint8(141);
      writeValue(buffer, value.encode());
    } else {
      super.writeValue(buffer, value);
    }
  }

  @override
  Object? readValueOfType(int type, ReadBuffer buffer) {
    switch (type) {
      case 129:
        return IceServerMessage.decode(readValue(buffer)!);
      case 130:
        return ConfigMessage.decode(readValue(buffer)!);
      case 131:
        return StartOptionsMessage.decode(readValue(buffer)!);
      case 132:
        return AccountConfigMessage.decode(readValue(buffer)!);
      case 133:
        return AccountMessage.decode(readValue(buffer)!);
      case 134:
        return CallMessage.decode(readValue(buffer)!);
      case 135:
        return StartResultMessage.decode(readValue(buffer)!);
      case 136:
        return CallInfoMessage.decode(readValue(buffer)!);
      case 137:
        return MediaStatsMessage.decode(readValue(buffer)!);
      case 138:
        return AudioDeviceMessage.decode(readValue(buffer)!);
      case 139:
        return ExternalAudioFormatMessage.decode(readValue(buffer)!);
      case 140:
        return AudioRouteMessage.decode(readValue(buffer)!);
